    crate::testport::assert_eq(it_own(nodes, text, c1, &crate::testport::text_blob("gamma delta")[..]), 1, "gamma delta: the space between them is inside the span");
    crate::testport::assert_eq(it_own(nodes, text, c2, &crate::testport::text_blob("epsilon")[..]), 1, "epsilon");
