pub(crate) fn it_glyph(mut gl: &mut crate::port::Cells, x0: i32, x1: i32, cp: i32, word: i32, size: i32, by: i32) -> i32 {
    // A glyph of word `word` in font 0: its box on the line at y 6400, its size and its baseline's y.
    let g: i32 = gl_new(gl, 1, x0, 6400, x1, 7600, cp, -1, 0, word);
    gl_set(gl, g, gf_font(), 0);
    gl_set(gl, g, gf_size(), size);
    gl_set(gl, g, gf_by0(), by);
    return g;
}
#[test]
fn test_a_raised_small_glyph_is_a_superscript_and_a_lowered_one_a_subscript() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ift: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let an: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let txt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    it_body(wd, ln, et, &crate::testport::text_blob("x2 beta H2O")[..]);
    it_fonts(ift);
    // word 6 is `x2`, word 8 `H2O`: the baseline of the line is y 7400, its text 11 pt
    wd_set(wd, 6, wf_gfirst(), 0);
    wd_set(wd, 6, wf_gcount(), 2);
    it_glyph(gl, 7200, 8000, 120, 6, 1100, 7400);
    it_glyph(gl, 8000, 8400, 50, 6, 700, 6900);
    wd_set(wd, 8, wf_gfirst(), 2);
    wd_set(wd, 8, wf_gcount(), 3);
    it_glyph(gl, 12800, 13600, 72, 8, 1100, 7400);
    it_glyph(gl, 13600, 14000, 50, 8, 700, 7900);
    it_glyph(gl, 14000, 14800, 79, 8, 1100, 7400);
    it_build(wd, ln, et, gl, ift, an, txt, nodes, attrs, regions, text, pages, ledger, layout);
    let sp: i32 = it_find(nodes, nk_span(), 0);
    let sb: i32 = it_find(nodes, nk_span(), 1);
    let cp: i32 = node_first_child(nodes, sp);
    let cb: i32 = node_first_child(nodes, sb);
    let nb: i32 = node_next(nodes, sb);
    crate::testport::assert_eq(node_sub(nodes, sp), 32, "the 2 of x2 is raised and small: a superscript");
    crate::testport::assert_eq(it_own(nodes, text, cp, &crate::testport::text_blob("2")[..]), 1, "and the span holds only it");
    crate::testport::assert_eq(node_sub(nodes, sb), 16, "the 2 of H2O is lowered: a subscript");
    crate::testport::assert_eq(it_own(nodes, text, cb, &crate::testport::text_blob("2")[..]), 1, "only it");
    crate::testport::assert_eq(it_find(nodes, nk_span(), 2), -1, "nothing else is marked");
    crate::testport::assert_eq(it_own(nodes, text, nb, &crate::testport::text_blob("O lorem ipsum dolor sit amet consectetur")[..]), 1, "the text after goes on");
    crate::testport::assert_eq(model_check(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
}
pub(crate) fn it_link_row(mut an: &mut crate::port::Cells, x0: i32, y0: i32, x1: i32, y1: i32, act: i32, ts: i32, tl: i32) -> i32 {
    // A link annotation row on page 0 (38 cells): its rectangle, the action (1 URI) and its target's run in `txt`.
    let at: i32 = crate::port::cells_len(an);
    let mut i: i32 = 0;
    while i < 38 {
        crate::port::cells_push(an, 0);
        i += 1;
    }
    crate::port::cells_set(an, at + 1, 1);
    crate::port::cells_set(an, at + 4, x0);
    crate::port::cells_set(an, at + 5, y0);
    crate::port::cells_set(an, at + 6, x1);
    crate::port::cells_set(an, at + 7, y1);
    crate::port::cells_set(an, at + 12, act);
    crate::port::cells_set(an, at + 13, ts);
    crate::port::cells_set(an, at + 14, tl);
    crate::port::cells_set(an, at + 15, -1);
    return at;
}
pub(crate) fn it_txt(mut txt: &mut crate::port::Cells, b: &[u8]) -> i32 {
    let mut i: i32 = 0;
    while i < crate::port::blob_len(b) {
        crate::port::cells_push(txt, crate::port::blob_u8(b, i));
        i += 1;
    }
    return 0;
}
#[test]
fn test_a_word_under_a_link_annotation_is_a_link() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let gl: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ift: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let an: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let txt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    it_body(wd, ln, et, &crate::testport::text_blob("alpha beta gamma delta")[..]);
    it_fonts(ift);
    it_txt(txt, &crate::testport::text_blob("https://example.org/x")[..]);
    // beta is at x 10000..12400 and gamma at 12800..15200, on y 6400..7600: the link covers beta and gamma
    it_link_row(an, 10000, 6400, 15200, 7600, 1, 0, 21);
    // a link to javascript, over delta, is no link
    it_txt(txt, &crate::testport::text_blob("javascript:x")[..]);
    it_link_row(an, 15600, 6400, 18000, 7600, 1, 21, 12);
    crate::testport::assert_eq(it_build(wd, ln, et, gl, ift, an, txt, nodes, attrs, regions, text, pages, ledger, layout), 1, "one link found");
    let p: i32 = it_find(nodes, nk_paragraph(), 0);
    let lk: i32 = it_find(nodes, nk_link(), 0);
    let a: i32 = node_attr(nodes, attrs, lk, fk_href());
    let lc: i32 = node_first_child(nodes, lk);
    let pf: i32 = node_first_child(nodes, p);
    let ln1: i32 = node_next(nodes, lk);
    crate::testport::assert_eq(it_find(nodes, nk_link(), 1), -1, "and only one");
    crate::testport::assert_eq(node_parent(nodes, lk), p, "in the paragraph");
    crate::testport::assert_eq(it_says(text, attr_value(attrs, a), attr_len(attrs, a), &crate::testport::text_blob("https://example.org/x")[..]), 1, "its href");
    crate::testport::assert_eq(it_own(nodes, text, lc, &crate::testport::text_blob("beta gamma")[..]), 1, "holds the two words and the space between them");
    crate::testport::assert_eq(it_own(nodes, text, pf, &crate::testport::text_blob("lorem ipsum dolor sit amet consectetur alpha ")[..]), 1, "the text before it");
    crate::testport::assert_eq(it_own(nodes, text, ln1, &crate::testport::text_blob(" delta lorem ipsum dolor sit amet consectetur")[..]), 1, "and after it, delta is not linked");
    crate::testport::assert_eq(model_check(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
}
pub(crate) fn it_block(mut nodes: &mut crate::port::Cells, mut regions: &mut crate::port::Cells, kind: i32, parent: i32, y0: i32, y1: i32) -> i32 {
    // A block of the kind on page 1 whose region is x 7200..50000 and y0..y1; answers its node.
    let n: i32 = node_new(nodes, kind, parent);
    node_add_region(nodes, regions, n, 1, 7200, y0, 50000, y1);
    return n;
}
pub(crate) fn it_link(mut nodes: &mut crate::port::Cells, mut attrs: &mut crate::port::Cells, mut text: &mut crate::port::Cells, parent: i32, page: i32, ypt: i32, inner: &[u8]) -> i32 {
    // A link to page `page` whose point is ypt points down, holding a span holding a text: answers the link.
    let lk: i32 = node_new(nodes, nk_link(), parent);
    let sp: i32 = node_new(nodes, nk_span(), lk);
    let tx: i32 = node_new(nodes, nk_text(), sp);
    let t0: i32 = crate::port::cells_len(text);
    node_set_sub(nodes, lk, page);
    node_set_aux(nodes, lk, (ypt + 1) * 32768);
    node_set_sub(nodes, sp, 1);
    text_append_utf8(text, inner, 0, crate::port::blob_len(inner));
    node_set_text(nodes, tx, t0, crate::port::cells_len(text) - t0);
    return lk;
}
pub(crate) fn it_rs(on: &mut crate::port::Cells, oa: &mut crate::port::Cells, orr: &mut crate::port::Cells, mut text: &mut crate::port::Cells, mut nodes: &mut crate::port::Cells, mut attrs: &mut crate::port::Cells, mut regions: &mut crate::port::Cells) -> i32 {
    let nm: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let stk: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let used: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let lay: &mut crate::port::Cells = &mut crate::port::Cells::new();
    return rs_run(on, oa, orr, text, nodes, attrs, regions, nm, stk, used, out, lay);
}
#[test]
fn test_an_internal_link_finds_the_block_it_names() {
    let on: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let oa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let orr: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let nodes: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let attrs: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let regions: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pages: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ledger: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let layout: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let st: &mut crate::port::Cells = &mut crate::port::Cells::new();
    model_init(on, oa, orr, text, pages, ledger, layout);
    page_new(pages, 1, 61200, 79200, 0, pk_vector());
    // a heading at y 20..30 pt, a paragraph (4 links in it) at 40..50, another at 80..90, a third on page 2
    it_block(on, orr, nk_heading(), 0, 2000, 3000);
    let p1: i32 = it_block(on, orr, nk_paragraph(), 0, 4000, 5000);
    it_link(on, oa, text, p1, 1, 18, &crate::testport::text_blob("see http://x.org/a")[..]);
    it_link(on, oa, text, p1, 1, 60, &crate::testport::text_blob("below")[..]);
    it_link(on, oa, text, p1, 1, 41, &crate::testport::text_blob("inside")[..]);
    it_link(on, oa, text, p1, 2, 5, &crate::testport::text_blob("later")[..]);
    it_block(on, orr, nk_paragraph(), 0, 8000, 9000);
    let p3: i32 = node_new(on, nk_paragraph(), 0);
    node_add_region(on, orr, p3, 2, 7200, 1000, 50000, 2000);
    // the nodes: 0 document, 1 heading, 2 paragraph, then each link is three (link, span, text): 3, 6, 9, 12; 15, 16
    crate::testport::assert_eq(it_rs(on, oa, orr, text, nodes, attrs, regions), 17, "the same Model, restructured");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 3, fk_target(), -1), 1, "a point a little above the heading is the heading");
    crate::testport::assert_eq(node_sub(nodes, 3), 0, "and the destination is taken out");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 6, fk_target(), -1), 15, "a point below the first paragraph names the next block");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 9, fk_target(), -1), 2, "a point inside a paragraph names it");
    crate::testport::assert_eq(node_attr_int_or(nodes, attrs, 12, fk_target(), -1), 16, "a point on page 2 names the block there");
    crate::testport::assert_eq(it_find(nodes, nk_link(), 4), -1, "and the bare URL under the first link is not made a link again");
    crate::testport::assert_eq(model_check(nodes, attrs, regions, text, pages, ledger, layout, st), 0, "in document order");
}
